        my $attributes = {
            class => $class_name,
            field_values => \%field_value_refs
        };
        my $node_id = $self->next_node_id();
        my $new_obj = Chalk::IR::Node->new(
            id            => $node_id,
            op            => 'New',
            inputs        => \@input_nodes,
            attributes    => $attributes,
