     1→# ABOUTME: Sea of Nodes IR node representation for Chalk compiler
     2→# ABOUTME: Represents a single node in the IR graph with operation type, inputs, and attributes
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Node {
     8→    field $id           :param :reader;
     9→    field $op           :param :reader;
    10→    field $inputs       :param :reader;
    11→    field $attributes   :param :reader;
    12→
    13→    method to_hash() {
    14→        return {
    15→            id           => $id,
    16→            op           => $op,
    17→            inputs       => $inputs,
    18→            attributes   => $attributes,
    19→        };
    20→    }
    21→
    22→    # Helper: Check if an attribute represents a constant value
    23→    sub _is_constant($attr) {
    24→        return defined($attr) && $attr->{op} eq 'Constant';
    25→    }
    26→
    27→    # Helper: Check for integer overflow in arithmetic operations
    28→    # Returns true if operation would overflow, false otherwise
    29→    # Uses 64-bit signed integer bounds (common on modern systems)
    30→    sub _would_overflow($op, $left, $right) {
    31→        my $max_int = 9223372036854775807;   # 2^63 - 1
    32→        my $min_int = -9223372036854775808;  # -2^63
    33→
    34→        if ($op eq 'Add') {
    35→            return 1 if $left > 0 && $right > 0 && $left > $max_int - $right;
    36→            return 1 if $left < 0 && $right < 0 && $left < $min_int - $right;
    37→        }
    38→        elsif ($op eq 'Subtract') {
    39→            return 1 if $left > 0 && $right < 0 && $left > $max_int + $right;
    40→            return 1 if $left < 0 && $right > 0 && $left < $min_int + $right;
    41→        }
    42→        elsif ($op eq 'Multiply') {
    43→            return 1 if $left != 0 && abs($right) > abs($max_int / $left);
    44→        }
    45→        return 0;
    46→    }
    47→
    48→    method peephole($graph) {
    49→        # Peephole optimization for constant folding
    50→        # Check if this is an arithmetic operation with constant operands
    51→        if ($op eq 'Add' || $op eq 'Multiply' || $op eq 'Subtract' || $op eq 'Divide') {
    52→            my $left  = $attributes->{left};
    53→            my $right = $attributes->{right};
    54→
    55→            # Both operands must be constants for folding
    56→            if (_is_constant($left) && _is_constant($right)) {
    57→                my $left_val  = $left->{value};
    58→                my $right_val = $right->{value};
    59→
    60→                # Skip optimization if it would overflow
    61→                return $self if _would_overflow($op, $left_val, $right_val);
    62→
    63→                my $result;
    64→
    65→                # Compute the result based on operation
    66→                if ($op eq 'Add') {
    67→                    $result = $left_val + $right_val;
    68→                }
    69→                elsif ($op eq 'Multiply') {
    70→                    $result = $left_val * $right_val;
    71→                }
    72→                elsif ($op eq 'Subtract') {
    73→                    $result = $left_val - $right_val;
    74→                }
    75→                elsif ($op eq 'Divide') {
    76→                    # Don't optimize division by zero - let it fail at runtime
    77→                    return $self if $right_val == 0;
    78→                    $result = int($left_val / $right_val);  # Integer division
    79→                }
    80→
    81→                # Return a new Constant node with the folded result
    82→                return Chalk::IR::Node->new(
    83→                    id            => $id,  # Reuse the same ID
    84→                    op            => 'Constant',
    85→                    inputs        => $inputs,
    86→                    attributes    => {
    87→                        value => $result,
    88→                        type  => 'Int',
    89→                    },
